export type BridgeClient = 'claude-code' | 'codex' | 'gemini-cli' | 'antigravity';
export type PlanAction = 'create' | 'update' | 'unchanged' | 'conflict';
export const BRIDGE_CLIENTS: readonly BridgeClient[];
export const PLAN_ACTIONS: readonly PlanAction[];
export const BRIDGE_PATH: string;
export function bridgeClientPath(c: BridgeClient): string;
export function bridgeRegistrationPath(c: BridgeClient): string;
export function bridgeUndoPath(id: string): string;
export function bridgeFilesPath(projectId: string): string;
export function bridgeProjectPath(projectId: string): string;
export function bridgeBackflowPath(projectId: string): string;
export type BridgeApp = { client: BridgeClient; name: string; enabled: boolean; configPath: string; registrationId: string | null; registeredAt: string | null; lastCallAt: string | null; lastTool: string | null };
export type BridgeFolder = { projectId: string; name?: string; folder?: string; filesEnabled: boolean; backflowEnabled: boolean; gitExclude: boolean; writtenAt: string | null; confirmedAt: string | null };
export type BridgeRegistration = { id: string; client: BridgeClient; configPath: string; existed: boolean; status: 'applied' | 'undone'; createdAt: string; undoneAt: string | null };
export type BridgeStatus = { clients: BridgeApp[]; projects: Array<BridgeFolder & { name: string; folder: string }>; registrations: BridgeRegistration[]; serverReady: boolean };
export type RegistrationPreview = { client: BridgeClient; name: string; configPath: string; action: PlanAction; reason?: string; diff: string; beforeSha256: string | null; afterSha256: string | null; previewHash: string; warnings: string[] };
export type FilesPreview = { projectId: string; folder: string; previewHash: string; conflicts: number; changes: number; files: Array<{ name: string; relative: string; action: PlanAction; reason?: string; diff: string }> };
export type BridgeEntry = { id: string; client: BridgeClient | null; projectId: string | null; action: string; detail: string | null; createdAt: string };
export function memoryBridgePath(path: string): { route: 'status' | 'audit' | 'client' | 'registration' | 'undo' | 'files' | 'backflow' | 'project'; id?: string; params?: Record<string, string> } | null;
export function memoryBridgeRoute(path: string): boolean;
export function allowedMemoryBridge(method: string, path: string, body?: unknown): boolean;
export function memoryBridgeResponse(path: string, status: number, body: unknown): unknown;
